      SUBROUTINE DSEXT2CC     CALCULATES PARTIAL DERIVATIVES OF SECOND-ORDER MATRIX ELEMENTSC     WITH RESPECT TO THE MAGNETIC FIELD OF A SEXTUPOLEC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17B.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'T.CIN'CC     LOCAL VARIABLESCC------------------------------------------------------------------------------      IB = IPTOJ(2)      IK2 = IPTOJ(4)      IF (IB .NE. 0) W2 = 2.0*DPARM*UNITI(9)/(PREF*AP**2)      IF (IK2 .NE. 0.0) W2 = 2.0*DPARM/UNITI(8)**3      S = - 0.25*W2*L      TV(1,1) = S*L      TV(2,1) = 2.0*S      S = - W2*L**3/24.0      TV(1,3) = S*L      TV(2,3) = 4.0*S      S = 0.25*W2*L      TV(1,6) = S*L      TV(2,6) = 2.0*S      S = W2*L**3/24.0      TV(1,10) = S*L      TV(2,10) = 4.0*S      S = - W2*L**2/6.0      TV(1,2) = S*L      TV(2,2) = 3.0*S      S = W2*L**2/6.0      TV(1,9) = S*L      TV(2,9) = 3.0*S      S = 0.5*W2*L      TV(3,4) = S*L      TV(4,4) = 2.0*S      S = W2*L**2/6.0      TV(3,5) = S*L      TV(3,7) = S*L      TV(4,5) = 3.0*S      TV(4,7) = 3.0*S      S = W2*L**3/12.0      TV(3,8) = S*L      TV(4,8) = 4.0*S      IF (SEXLIM) THEN        NV2 = IABS(TIE(I+2))        IF (NV2 .EQ. 100) THEN          IADR = IDATA(I+2)          NV2 = IABS(TIE(IADR))        ENDIF        CW = 1.0/SEXMAX**2        CA(1,1) = CA(1,1) + CW*B**2        CA(NV2+1,1) = CA(NV2+1,1) - CW*B*UNITI(9)        CA(NV2+1,NV2+1) = CA(NV2+1,NV2+1) + CW*UNITI(9)**2      ENDIF      RETURN      END